    'disposable_supabase_only_after_local_pass_and_explicit_authorization',
    'production_cutover_plan_only',
  ];
  if (!Array.isArray(receipt.rehearsal_order)) {
    errors.push('rehearsal_order_not_an_array');
  }
  const rehearsalOrder = asArray(receipt.rehearsal_order);
  const allRehearsalOrderPresent = expectedRehearsalOrder.every((item) => rehearsalOrder.includes(item));
  if (!allRehearsalOrderPresent) {
    errors.push('rehearsal_order_missing_expected_elements');
  }

  // Validate required_pre_cutover_artifacts array field
  if (rollback.required_pre_cutover_artifacts !== undefined && !Array.isArray(rollback.required_pre_cutover_artifacts)) {
    errors.push('required_pre_cutover_artifacts_not_an_array');
  }
  const requiredPreCutoverArtifacts = asArray(rollback.required_pre_cutover_artifacts);
  const expectedArtifacts = [
    receipt.output_artifacts?.receipt ?? DEFAULT_PATHS.receiptOut,
    receipt.output_artifacts?.validator ?? DEFAULT_PATHS.validatorOut,
    receipt.output_artifacts?.readback ?? DEFAULT_PATHS.readbackOut,
  ];
  const allArtifactsPresent = expectedArtifacts.every((art) => requiredPreCutoverArtifacts.includes(art));
  if (!allArtifactsPresent) {
    errors.push('required_pre_cutover_artifacts_missing_expected_elements');
  }
